  async runEstimateExport(mode){
    if(this.state.estimateExportBusy)return;
    const p=this.cur();if(!p)return;
    const adjustment=this.commitEstimatePercent(p.id);
    const x=this.state.exp,ed=this.ed(p.id);
    const exportEstimate=(rooms,edits)=>withEstimateImages(est(rooms,edits),NOM);
    const opts={project:p,company:window.MagicEstimate.getCompanyDetails(this.state.profile),est:exportEstimate(p.rooms,ed),adjustment,showAdjustment:window.MagicEstimate.estimateAdjustmentVisibility(p.estimateExportOptions),template:this.state.profile?.estimateTemplate,
      cols:x.cols,type:x.type,rooms:p.rooms.filter(r=>r.on).map(r=>Object.assign({},r,{est:exportEstimate([r],{})}))};
    const action={download:'downloadEstimate',share:'shareEstimate',preview:'previewEstimate'}[mode];
    if(!action||typeof window.MagicEstimate[action]!=='function'){this.toast('Экспорт не загрузился. Обновите страницу');return;}
    this.setState({estimateExportBusy:true});
    try{
      const result=await window.MagicEstimate[action](opts),status=result&&result.status||result;
      if(status==='cancelled')return;
      if(!['downloaded','shared','previewed'].includes(status))throw new Error('Экспорт не завершён');
      if(mode!=='preview'){
        this.upd(p.id,project=>Object.assign({},project,{status:project.status==='order'?'estimate':project.status}));
        this.toast(status==='shared'?'Смета отправлена':'PDF сохранён');
      }
    }catch(error){this.toast(error&&error.message?'Не удалось подготовить смету: '+error.message:'Не удалось подготовить смету');}
    finally{this.setState({estimateExportBusy:false});}
  }

  pArea(p){return p.rooms.filter(r=>r.on).reduce((s,r)=>s+geom(r.v,r.holes).a,0);}
  upd(pid,fn){this.setState(s=>({projects:s.projects.map(p=>p.id===pid?ensureProjectCatalog(fn(Object.assign({},p)),desktopCatalog()):p)}));}
  updRoom(fn){const pid=this.state.curId,rid=this.state.tab;this.upd(pid,p=>({...p,rooms:p.rooms.map(r=>r.id===rid?captureRoomCatalog(fn(cloneProjectData(r)),desktopCatalog()):r)}));}
  toast(t){clearTimeout(this._tt);this.setState({toast:t});this._tt=setTimeout(()=>this.setState({toast:null}),2400);}
  go(screen,extra){if(screen==='btnEd'&&!this._presetDraft)this.beginPresetDraft(extra&&extra.be);this.setState(Object.assign({screen,sheet:null,fin:null},screen==='calc'&&this.state.screen!=='calc'?{collapsed:{},calcFold:{}}:{},extra||{}));}
